    choices: ['Low-variation decoding suits structured extraction: still validate outputs and evidence.', 'Broader sampling suits brainstorming: expect more variability and evaluate usefulness.'],
    trap: 'Temperature changes selection probabilities, not model knowledge.', lab: 'sampling',
    check: { question: 'Will temperature 0 guarantee a correct refund policy?', options: ['Yes, because it is deterministic', 'No, likely text can still be false', 'Yes, if top-p is also 1'], correct: 1, why: ['Repeatability and factual correctness are different properties.', 'Use authoritative evidence and evaluate correctness independently of decoding.', 'This configuration does not add or verify facts.'] },
