    interview: { question: 'How do you make LLM tool calls safe and reliable?', points: ['Validate arguments and enforce server-side identity and least privilege.', 'Gate consequential actions and use idempotency for retries.', 'Inspect results, record state and handle unknown outcomes through reconciliation.'], followUp: 'What if the tool output tells the model to ignore the user?' }, sources: ['agents', 'security'],
