    interview: { question: 'What distinguishes an agent from a workflow?', points: ['A workflow follows predefined control flow; an agent selects actions dynamically.', 'Both need explicit state, reliable tools and application-enforced constraints.', 'Choose autonomy only when observation-dependent decisions improve measured outcomes.'], followUp: 'What are your termination and escalation conditions?' }, sources: ['agents'],
